7	public static class DataSeeder
8	{
9	    public static async Task SeedIfEmptyAsync(AppDbContext db, string webRootOrContentRoot, ILogger logger)
10	    {
11	        if (await db.Categories.AnyAsync())
12	        {
13	            return;
14	        }
15	
16	        var path = Path.Combine(webRootOrContentRoot, "Data", "anfangsdatenbestand.json");
17	        if (!File.Exists(path))
18	        {
19	            logger.LogWarning("Anfangsdatenbestand nicht gefunden unter {Path}, überspringe Seeding.", path);
20	            return;
21	        }
22	
23	        var json = await File.ReadAllTextAsync(path);
24	        var seed = JsonSerializer.Deserialize<SeedRoot>(json, new JsonSerializerOptions
25	        {
26	            PropertyNameCaseInsensitive = true,
27	        }) ?? throw new InvalidOperationException("Anfangsdatenbestand konnte nicht gelesen werden.");
28	
29	        var categoriesBySeedId = new Dictionary<string, Category>();
30	        var suppliersBySeedId = new Dictionary<string, Supplier>();
31	
32	        foreach (var seedCategory in seed.Kategorien)
33	        {
34	            var category = new Category { Name = seedCategory.Name };
35	            categoriesBySeedId[seedCategory.Id] = category;
36	            db.Categories.Add(category);
37	
38	            foreach (var seedSub in seedCategory.Unterkategorien)
39	            {
40	                var subcategory = new Category
41	                {
42	                    Name = seedSub.Name,
43	                    ParentCategory = category,
44	                    PropertyNames = seedSub.Eigenschaften,
